import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"容量分析","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/space-analyzer.md","filePath":"ja-JP/user-guide/space-analyzer.md","lastUpdated":1786468666000}'),i={name:"ja-JP/user-guide/space-analyzer.md"};function l(n,a,s,d,p,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="容量分析" tabindex="-1">容量分析 <a class="header-anchor" href="#容量分析" aria-label="Permalink to &quot;容量分析&quot;">​</a></h1><p>容量分析は、Lertaro の既存のファイルインデックスを SpaceSniffer のような高速な視覚表示に変換します。ディスクを走査しないため、複数のドライブに数百万件の項目があってもすばやく開けます。</p><h2 id="容量分析を開く" tabindex="-1">容量分析を開く <a class="header-anchor" href="#容量分析を開く" aria-label="Permalink to &quot;容量分析を開く&quot;">​</a></h2><p>Lertaro のトレイアイコンを右クリックし、<strong>容量分析</strong>を選択します。最初の画面には、Lertaro が現在読み込んでいるすべてのインデックスが表示されます。ドライブまたはフォルダーをマウスの左ボタンでダブルクリックするとその中に移動でき、上矢印またはパンくずリストの任意の項目で上の階層に戻れます。</p><h2 id="表示と操作" tabindex="-1">表示と操作 <a class="header-anchor" href="#表示と操作" aria-label="Permalink to &quot;表示と操作&quot;">​</a></h2><ul><li>左側のツリーマップでは、大きな項目ほど広い面積を占めます。明暗は相対的なサイズを表し、枠線の違いでフォルダーとファイルを区別します。</li><li>右側のリストには同じ項目がサイズの降順で表示されます。どちらかで項目を選択すると、もう一方でも同期して強調表示されます。</li><li>カードまたはリスト行を右クリックすると、検索結果と同じアクションメニューが開きます。開く、場所を表示、コピー、および該当するプラグインアクションを利用できます。</li><li>ツールチップは名前またはサイズが省略された場合にのみ表示されます。</li></ul><h2 id="集計対象" tabindex="-1">集計対象 <a class="header-anchor" href="#集計対象" aria-label="Permalink to &quot;集計対象&quot;">​</a></h2><p>Lertaro で有効になっているインデックスにすでに存在する項目だけが集計され、容量分析がファイルシステムを走査して不足分を補うことはありません。除外対象と未インデックスの内容は集計されません。隠し項目とシステム項目は個別には表示されませんが、そのサイズは表示中の上位フォルダーの合計に含まれる場合があります。</p><p>表示されるのはファイルの論理サイズであり、ディスク上の割り当て済み容量ではありません。フォルダーの合計にはインデックス済みの子孫が含まれ、ハードリンクされたデータは一度だけ数えられるため、Windows エクスプローラーやセクターレベルのディスク分析ツールとは結果が異なる場合があります。</p><p>ウィンドウを開いたときと<strong>更新</strong>を押したときには、ライブモニターがすでに受け取ったファイル変更を含む最新のメモリ内インデックス状態が照会されます。容量分析がインデックスキャッシュファイルを別途開いたり再読み込みしたりすることはありません。ウィンドウを閉じると、描画済みの項目と共有 UI キャッシュが解放されます。</p>',10)])])}const _=e(i,[["render",l]]);export{u as __pageData,_ as default};
